-- Universal learner memorisation. Curriculum definitions reuse Academy Modules;
-- these records do not infer task completion from class curriculum progress.
CREATE TABLE memorisation_catalogue_state (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),
  revision INTEGER NOT NULL CHECK(revision>=1)
);
CREATE TABLE memorisation_modules (
  module_id TEXT PRIMARY KEY COLLATE NOCASE REFERENCES academy_module_catalogue(module_id),
  subject TEXT NOT NULL CHECK(subject IN ('SURAHS','DUAS')),
  level TEXT NOT NULL CHECK(length(trim(level)) BETWEEN 1 AND 60),
  sort_order INTEGER NOT NULL
);
CREATE TABLE memorisation_tasks (
  task_id TEXT PRIMARY KEY COLLATE NOCASE NOT NULL,
  module_id TEXT COLLATE NOCASE NOT NULL REFERENCES memorisation_modules(module_id),
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 240),
  sort_order INTEGER NOT NULL,
  UNIQUE(module_id,name)
);
CREATE INDEX memorisation_tasks_module ON memorisation_tasks(module_id,sort_order);
CREATE TABLE learner_task_progress (
  account_id TEXT COLLATE NOCASE NOT NULL REFERENCES accounts(account_id),
  task_id TEXT COLLATE NOCASE NOT NULL REFERENCES memorisation_tasks(task_id),
  complete INTEGER NOT NULL CHECK(complete IN (0,1)),
  confirmed INTEGER NOT NULL CHECK(confirmed IN (0,1) AND confirmed<=complete),
  revision INTEGER NOT NULL CHECK(revision>=1),
  completed_at TEXT,
  confirmed_at TEXT,
  confirmed_by TEXT COLLATE NOCASE REFERENCES accounts(account_id),
  updated_at TEXT NOT NULL,
  CHECK((complete=1)=(completed_at IS NOT NULL)),
  CHECK((confirmed=1)=(confirmed_at IS NOT NULL AND confirmed_by IS NOT NULL)),
  PRIMARY KEY(account_id,task_id)
);
CREATE INDEX learner_task_progress_task ON learner_task_progress(task_id,account_id);
UPDATE academy_write_state SET version=version+1 WHERE singleton=1;
